// Benchmark driver.
//
// Every number printed here is measured on this machine, with this build, against
// this repository's own binaries. The labels are deliberate and honest:
//
//   REAL        measured end to end on the current hardware and filesystem,
//               including durable flushes; nothing is simulated.
//   SYNTHETIC   the facility data driving the measurement is generated by this
//               driver because no real facility telemetry exists here.
//   UNSUPPORTED no claim is made. There is no BMS, DCIM, electrical, cooling, or
//               multi-node instrumentation available to this repository, so no
//               such throughput or latency is reported.

#include <algorithm>
#include <chrono>
#include <cstdint>
#include <filesystem>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

#include "fel/fel.hpp"

namespace {

using namespace fel;
using Clock = std::chrono::steady_clock;

struct Measurement {
    std::string name;
    std::string label;
    std::string unit;
    double value{0.0};
    std::string detail;
    std::size_t repetitions{0};
};

std::vector<Measurement>& results() {
    static std::vector<Measurement> storage;
    return storage;
}

void record(const std::string& name, const std::string& label, const std::string& unit, double value,
            const std::string& detail, std::size_t repetitions) {
    results().push_back(Measurement{name, label, unit, value, detail, repetitions});
}

double seconds_since(const Clock::time_point& start) {
    return std::chrono::duration<double>(Clock::now() - start).count();
}

class Scratch {
public:
    explicit Scratch(const std::string& label) {
        std::error_code error;
        const std::string name = "fel-bench-" + label;
        for (int attempt = 0; attempt < 64; ++attempt) {
            path_ = std::filesystem::temp_directory_path(error) /
                    (name + "-" + std::to_string(attempt));
            if (std::filesystem::create_directories(path_, error) && !error) {
                return;
            }
            error.clear();
        }
        throw std::runtime_error{"cannot create a benchmark scratch directory"};
    }

    ~Scratch() {
        std::error_code error;
        std::filesystem::remove_all(path_, error);
    }

    const std::filesystem::path& path() const { return path_; }

private:
    std::filesystem::path path_;
};

Digest evidence(const std::string& label) { return Sha256::hash(label); }

Instant bench_instant(const char* text) { return Instant::parse_iso8601(text).value(); }

constexpr std::int64_t kSecondsPerSlot = 60;

// Each measurement from one source occupies its own slot, because the ledger
// refuses overlapping measurements from the same source.
Interval bench_interval(int slot) {
    const Instant base = bench_instant("2026-01-01T00:00:00Z");
    const Instant start = base.add_seconds(slot * kSecondsPerSlot).value();
    const Instant end = base.add_seconds((slot + 1) * kSecondsPerSlot).value();
    return Interval::make(start, end).value();
}

Interval bench_scope(int slots) {
    const Instant base = bench_instant("2026-01-01T00:00:00Z");
    const Instant end = base.add_seconds(static_cast<std::int64_t>(slots) * kSecondsPerSlot).value();
    return Interval::make(base, end).value();
}

// Fills a ledger with synthetic evidence: sources, generations, measurements, and
// a full classification split. Returns the elapsed seconds.
double populate(const std::filesystem::path& directory, int sources, int per_source) {
    const Clock::time_point start = Clock::now();
    Result<Ledger> created =
        Ledger::create(directory, LedgerId::parse("bench-ledger").value(), "fel-bench");
    if (!created.ok()) {
        throw std::runtime_error{"cannot create the benchmark ledger"};
    }
    const Instant base = bench_instant("2026-01-01T00:00:00Z");
    Ledger& ledger = created.value();
    for (int source_index = 0; source_index < sources; ++source_index) {
        const std::string source_name = "bench-source-" + std::to_string(source_index);
        RegisterSourceRequest source;
        source.source = SourceId::parse(source_name).value();
        source.kind = SourceKind::Meter;
        source.unit = Unit::KilowattHour;
        source.label = "synthetic benchmark meter";
        source.context.now = base;
        if (!ledger.register_source(source).ok()) {
            throw std::runtime_error{"benchmark source registration failed"};
        }
        PublishGenerationRequest generation;
        generation.source = source.source;
        generation.generation = Generation{1};
        generation.evidence = evidence(source_name);
        generation.method = "synthetic";
        generation.context.now = base;
        if (!ledger.publish_generation(generation).ok()) {
            throw std::runtime_error{"benchmark generation publication failed"};
        }
        for (int entry_index = 0; entry_index < per_source; ++entry_index) {
            const std::string entry_name =
                "bench-entry-" + std::to_string(source_index) + "-" + std::to_string(entry_index);
            RecordMeasurementRequest measurement;
            measurement.entry = EntryId::parse(entry_name).value();
            measurement.interval = bench_interval(entry_index);
            measurement.source = source.source;
            measurement.generation = Generation{1};
            measurement.quantity = Quantity{Rational{100}, Unit::KilowattHour};
            measurement.evidence = evidence(entry_name);
            measurement.context.now = base;
            if (!ledger.record_measurement(measurement).ok()) {
                throw std::runtime_error{"benchmark measurement failed"};
            }
            RecordClassificationRequest allocation;
            allocation.allocation =
                AllocationId::parse("bench-alloc-" + std::to_string(source_index) + "-" +
                                    std::to_string(entry_index))
                    .value();
            allocation.entry = measurement.entry;
            allocation.klass = ServiceClass::Useful;
            allocation.quantity = Quantity{Rational{100}, Unit::KilowattHour};
            allocation.evidence = evidence(entry_name + "-classification");
            allocation.context.now = base;
            if (!ledger.record_classification(allocation).ok()) {
                throw std::runtime_error{"benchmark classification failed"};
            }
        }
    }
    return seconds_since(start);
}

}  // namespace

namespace {

void benchmark_exact_arithmetic(std::size_t iterations) {
    const Clock::time_point start = Clock::now();
    Rational accumulator = *Rational::make(1, 3);
    const Rational step = *Rational::make(7, 11);
    const Rational ceiling = *Rational::make(1000000, 1);
    std::uint64_t checksum = 0;
    for (std::size_t index = 0; index < iterations; ++index) {
        const Result<Rational> sum = accumulator.add(step);
        const Result<Rational> product = accumulator.multiply(step);
        if (!sum.ok() || !product.ok()) {
            throw std::runtime_error{"exact arithmetic failed inside the benchmark"};
        }
        accumulator = sum.value();
        checksum += static_cast<std::uint64_t>(product.value().numerator() & 0xFFFF);
        if (accumulator.compare(ceiling) > 0) {
            accumulator = *Rational::make(1, 3);
        }
    }
    const double elapsed = seconds_since(start);
    record("exact_rational_operations", "REAL", "ops/s",
           static_cast<double>(iterations) / elapsed,
           "checked rational add plus multiply with 128-bit intermediates; checksum " +
               std::to_string(checksum % 1000U),
           iterations);
}

void benchmark_digest(std::size_t mebibytes) {
    const std::string block(1024U * 1024U, 'f');
    const Clock::time_point start = Clock::now();
    Digest digest{};
    for (std::size_t index = 0; index < mebibytes; ++index) {
        digest = Sha256::hash(std::string_view{block});
    }
    const double elapsed = seconds_since(start);
    record("sha256_throughput", "REAL", "MiB/s", static_cast<double>(mebibytes) / elapsed,
           "in-tree SHA-256 over one mebibyte blocks; final digest " +
               digest.to_hex().substr(0, 12),
           mebibytes);
}

void benchmark_durable_commits(int sources, int per_source) {
    Scratch scratch("append");
    std::vector<double> samples;
    for (int repetition = 0; repetition < 3; ++repetition) {
        const std::filesystem::path directory =
            scratch.path() / ("run-" + std::to_string(repetition));
        samples.push_back(populate(directory, sources, per_source));
    }
    std::sort(samples.begin(), samples.end());
    const double median = samples[samples.size() / 2U];
    const auto records = static_cast<double>(sources) * static_cast<double>(per_source) * 2.0 +
                         static_cast<double>(sources) * 2.0 + 3.0;
    record("durable_commit_throughput", "REAL", "records/s", records / median,
           "full command path: validate, frame, append, flush, re-index, over synthetic facility data",
           samples.size());
    record("durable_commit_latency", "REAL", "us/record", median * 1e6 / records,
           "median of three runs of the same synthetic workload", samples.size());
}

void benchmark_fold(int sources, int per_source) {
    Scratch scratch("fold");
    const std::filesystem::path directory = scratch.path() / "ledger";
    populate(directory, sources, per_source);
    Result<Ledger> ledger =
        Ledger::open(directory, StoreOptions{OpenMode::Reader, false, {}, {}, {}});
    if (!ledger.ok()) {
        throw std::runtime_error{"cannot reopen the benchmark ledger"};
    }
    std::vector<double> samples;
    std::size_t record_count = 0;
    for (int repetition = 0; repetition < 5; ++repetition) {
        const Clock::time_point start = Clock::now();
        const Result<LedgerView> view = LedgerView::fold(ledger.value().store().records(), Instant{});
        const double elapsed = seconds_since(start);
        if (!view.ok()) {
            throw std::runtime_error{"fold failed inside the benchmark"};
        }
        record_count = ledger.value().store().records().size();
        samples.push_back(elapsed);
    }
    std::sort(samples.begin(), samples.end());
    const double median = samples[samples.size() / 2U];
    record("journal_fold_throughput", "REAL", "records/s", static_cast<double>(record_count) / median,
           "full deterministic replay of the committed journal", samples.size());
}

void benchmark_reconcile(int sources, int per_source) {
    Scratch scratch("reconcile");
    const std::filesystem::path directory = scratch.path() / "ledger";
    populate(directory, sources, per_source);
    Result<Ledger> ledger =
        Ledger::open(directory, StoreOptions{OpenMode::Reader, false, {}, {}, {}});
    if (!ledger.ok()) {
        throw std::runtime_error{"cannot reopen the benchmark ledger"};
    }
    ReconcileRequest request;
    request.interval = bench_scope(per_source);
    std::vector<double> samples;
    for (int repetition = 0; repetition < 5; ++repetition) {
        const Clock::time_point start = Clock::now();
        const Result<ReconciliationReport> report = ledger.value().reconcile(request);
        const double elapsed = seconds_since(start);
        if (!report.ok() || !report.value().closed) {
            throw std::runtime_error{"benchmark reconciliation did not close"};
        }
        samples.push_back(elapsed);
    }
    std::sort(samples.begin(), samples.end());
    const double median = samples[samples.size() / 2U];
    record("reconciliation_latency", "REAL", "ms/report", median * 1e3,
           "scoped reconciliation over a fully classified interval", samples.size());
    record("reconciliation_entries", "SYNTHETIC", "entries",
           static_cast<double>(sources) * static_cast<double>(per_source),
           "size of the synthetic evidence set the report covers", samples.size());
}

void benchmark_restart(int sources, int per_source) {
    Scratch scratch("recovery");
    const std::filesystem::path directory = scratch.path() / "ledger";
    populate(directory, sources, per_source);
    std::vector<double> samples;
    std::size_t record_count = 0;
    for (int repetition = 0; repetition < 5; ++repetition) {
        const Clock::time_point start = Clock::now();
        Result<Ledger> reopened =
            Ledger::open(directory, StoreOptions{OpenMode::Writer, false, {}, {}, {}});
        const double elapsed = seconds_since(start);
        if (!reopened.ok()) {
            throw std::runtime_error{"benchmark reopen failed"};
        }
        record_count = reopened.value().store().records().size();
        samples.push_back(elapsed);
    }
    std::sort(samples.begin(), samples.end());
    const double median = samples[samples.size() / 2U];
    record("restart_recovery_time", "REAL", "ms", median * 1e3,
           "reopen, chain verification, tail recovery, and epoch adoption", samples.size());
    record("restart_recovery_records", "SYNTHETIC", "records", static_cast<double>(record_count),
           "committed records verified during recovery", samples.size());
}

void benchmark_compaction(int sources, int per_source) {
    Scratch scratch("compaction");
    const std::filesystem::path directory = scratch.path() / "ledger";
    populate(directory, sources, per_source);
    Result<Ledger> ledger =
        Ledger::open(directory, StoreOptions{OpenMode::Writer, false, {}, {}, {}});
    if (!ledger.ok()) {
        throw std::runtime_error{"cannot reopen the benchmark ledger"};
    }
    const auto bytes_before = static_cast<double>(
        std::filesystem::file_size(directory / ledger.value().store().active_segment_name()));
    const Clock::time_point start = Clock::now();
    const Result<std::uint64_t> dropped = ledger.value().compact();
    const double elapsed = seconds_since(start);
    if (!dropped.ok()) {
        throw std::runtime_error{"benchmark compaction failed"};
    }
    record("compaction_time", "REAL", "ms", elapsed * 1e3,
           "snapshot publication plus segment re-anchoring through the manifest", 1);
    record("compaction_segment_bytes", "SYNTHETIC", "bytes", bytes_before,
           "size of the synthetic journal that was compacted", 1);
}

void record_unsupported() {
    record("bms_dcim_telemetry_throughput", "UNSUPPORTED", "n/a", 0.0,
           "no building management, DCIM, electrical, or cooling instrumentation is available",
           0);
    record("multi_node_cluster_throughput", "UNSUPPORTED", "n/a", 0.0,
           "no multi-node deployment exists; only single-host measurements and multiprocess "
           "correctness tests are performed",
           0);
    record("real_facility_energy_savings", "UNSUPPORTED", "n/a", 0.0,
           "no real facility was instrumented, so no efficiency outcome is claimed", 0);
}

}  // namespace

int main(int argc, char** argv) {
    int scale = 1;
    for (int index = 1; index < argc; ++index) {
        const std::string argument = argv[index];
        if (argument.rfind("--scale=", 0) == 0) {
            scale = std::max(1, std::stoi(argument.substr(8)));
        }
    }
    const int sources = 2 * scale;
    const int per_source = 40 * scale;

    std::cout << "facility efficiency ledger benchmark" << std::endl;
    std::cout << "  runtime      : " << kRuntimeIdentity << " " << library_version_string()
              << std::endl;
    std::cout << "  scale factor : " << scale << std::endl;
    std::cout << "  synthetic set: " << sources << " sources x " << per_source << " measurements"
              << std::endl
              << std::endl;

    try {
        benchmark_exact_arithmetic(static_cast<std::size_t>(200000) * static_cast<std::size_t>(scale));
        benchmark_digest(static_cast<std::size_t>(64) * static_cast<std::size_t>(scale));
        benchmark_durable_commits(sources, per_source);
        benchmark_fold(sources, per_source);
        benchmark_reconcile(sources, per_source);
        benchmark_restart(sources, per_source);
        benchmark_compaction(sources, per_source);
        record_unsupported();
    } catch (const std::exception& error) {
        std::cerr << "benchmark failed: " << error.what() << std::endl;
        return 1;
    }

    std::cout << "measurement                              label        unit             value" << std::endl;
    for (const Measurement& measurement : results()) {
        std::string name = measurement.name;
        if (name.size() < 40U) {
            name.append(40U - name.size(), ' ');
        }
        std::string label = measurement.label;
        if (label.size() < 12U) {
            label.append(12U - label.size(), ' ');
        }
        std::string unit = measurement.unit;
        if (unit.size() < 14U) {
            unit.append(14U - unit.size(), ' ');
        }
        std::cout << name << " " << label << " " << unit << " " << measurement.value << std::endl;
        std::cout << "    " << measurement.detail << std::endl;
    }

    Json json = Json::object();
    json.set("runtime", Json::text(std::string(kRuntimeIdentity)));
    json.set("version", Json::text(std::string(library_version_string())));
    json.set("scale", Json::integer(scale));
    Json entries = Json::array();
    for (const Measurement& measurement : results()) {
        Json item = Json::object();
        item.set("detail", Json::text(measurement.detail));
        item.set("label", Json::text(measurement.label));
        item.set("name", Json::text(measurement.name));
        item.set("repetitions", Json::uinteger(measurement.repetitions));
        item.set("unit", Json::text(measurement.unit));
        item.set("value", Json::number(std::to_string(measurement.value)));
        entries.push(std::move(item));
    }
    json.set("measurements", std::move(entries));
    std::cout << std::endl << json.dump() << std::endl;
    return 0;
}
